static double now(clockid_t c) { struct timespec t; clock_gettime(c,&t); return t.tv_sec+t.tv_nsec/1e9; }
int main(int argc, char **argv) {
 double wall=now(CLOCK_MONOTONIC), cpu=now(CLOCK_PROCESS_CPUTIME_ID);
 if(argc>1 && strcmp(argv[1],"sync")==0) {
  int fd=open("/home/ubuntu/graphforge-1480/workspace/control-file",O_CREAT|O_EXCL|O_RDWR,0600);
  int dir=open("/home/ubuntu/graphforge-1480/workspace",O_RDONLY|O_DIRECTORY);
  if(fd<0 || dir<0 || write(fd,"test",4)!=4 || fsync(fd) || fdatasync(fd) || fsync(dir)) { perror("control sync"); return 1; }
  close(fd); close(dir);
 }
 else if(argc>1 && argv[1][0]=='s') { struct timespec t={1,0}; nanosleep(&t,NULL); }
 else { volatile unsigned long x=1; while(now(CLOCK_PROCESS_CPUTIME_ID)-cpu<1.) for(int i=0;i<10000;i++) x=x*1664525+1013904223; }
 printf("{\"wall_s\":%.9f,\"cpu_s\":%.9f}\n",now(CLOCK_MONOTONIC)-wall,now(CLOCK_PROCESS_CPUTIME_ID)-cpu);
}

